-- Backend Engineering ("The Fracture") Act 3 -- "Asynchronous City" content.
-- 1 campaign, 2 operations, 12 missions (11 lessons + boss), following the
-- same campaigns -> operations -> missions -> dialogue -> objectives ->
-- challenges -> hints pattern as Act 1 (20260810040000_backend_act1_content.sql)
-- and Act 2 (20260810050000_backend_act2_content.sql).
-- References the world-be-3 spine row already inserted by
-- 20260810045000_backend_acts2_10_and_arc2.sql.

insert into public.campaigns (id, world_id, slug, title, description, sort_order) values
  ('campaign-be3', 'world-be-3', 'asynchronous-city', '3A - Asynchronous City', 'Find out exactly what freezes a server and why -- synchronous execution, callbacks, promises, the event loop, and the CPU-bound work that can lock all of it down at once.', 1);

insert into public.operations (id, campaign_id, slug, title, description, sort_order) values
  ('operation-be3-1', 'campaign-be3', 'learning-to-wait', 'Learning to Wait', 'Synchronous execution, callbacks, promises, async/await and the event loop underneath all of them.', 1),
  ('operation-be3-2', 'campaign-be3', 'what-freezes-a-server', 'What Freezes a Server', 'Blocking work, CPU-bound tasks, worker threads, streams and buffers -- learned by finding out exactly what locks the event loop and why.', 2);

insert into public.missions (
  id, world_id, campaign_id, operation_id, slug, title, description, difficulty,
  character_ids, prerequisites, required_skills, lab, rewards, is_boss, sort_order
) values
  ('mission-be3-01', 'world-be-3', 'campaign-be3', 'operation-be3-1', 'synchronous-vs-asynchronous', 'Synchronous vs Asynchronous', 'The server survived Port 8080, stayed up a week, then went quiet mid-shift -- not crashed, just unresponsive for exactly as long as one report took to generate. It starts with what ''blocking'' actually means.', 'beginner', ARRAY['mira','forge'], null, null, '{"type":"simulation","simulationId":"sync-vs-async-sim"}'::jsonb, '{"xp":90,"credits":15}'::jsonb, false, 1),
  ('mission-be3-02', 'world-be-3', 'campaign-be3', 'operation-be3-1', 'callbacks', 'Callbacks', 'The original way Node handled work that finishes later: hand it a function, and it calls you back. Simple in isolation, and not always simple stacked three deep.', 'beginner', ARRAY['forge'], '{"requiredMissionIds":["mission-be3-01"]}'::jsonb, null, '{"type":"simulation","simulationId":"callback-pattern-sim"}'::jsonb, '{"xp":95,"credits":15}'::jsonb, false, 2),
  ('mission-be3-03', 'world-be-3', 'campaign-be3', 'operation-be3-1', 'promises', 'Promises', 'An object that represents work that hasn''t finished yet, with exactly one of three states waiting at the end of it.', 'beginner', ARRAY['forge'], '{"requiredMissionIds":["mission-be3-02"]}'::jsonb, null, '{"type":"simulation","simulationId":"promise-chain-sim"}'::jsonb, '{"xp":100,"credits":15}'::jsonb, false, 3),
  ('mission-be3-04', 'world-be-3', 'campaign-be3', 'operation-be3-1', 'async-await', 'async/await', 'Syntax that makes asynchronous code read like it runs top to bottom. It doesn''t change what''s actually happening underneath -- only how it looks while it happens.', 'beginner', ARRAY['forge','mira'], '{"requiredMissionIds":["mission-be3-03"]}'::jsonb, null, '{"type":"simulation","simulationId":"async-await-sim"}'::jsonb, '{"xp":100,"credits":18}'::jsonb, false, 4),
  ('mission-be3-05', 'world-be-3', 'campaign-be3', 'operation-be3-1', 'event-loop', 'Event Loop', 'The actual mechanism underneath every callback, promise and await so far: one call stack, one thread, and a loop deciding what runs next.', 'beginner', ARRAY['forge','mira'], '{"requiredMissionIds":["mission-be3-04"]}'::jsonb, null, '{"type":"simulation","simulationId":"event-loop-sim"}'::jsonb, '{"xp":105,"credits":18}'::jsonb, false, 5),
  ('mission-be3-06', 'world-be-3', 'campaign-be3', 'operation-be3-1', 'microtasks-and-timers', 'Microtasks and Timers', 'Not every queue is equal. Promises jump ahead of timers, and a 0ms setTimeout was never a promise to run at zero milliseconds.', 'beginner', ARRAY['forge'], '{"requiredMissionIds":["mission-be3-05"]}'::jsonb, null, '{"type":"simulation","simulationId":"microtask-timing-sim"}'::jsonb, '{"xp":110,"credits":20}'::jsonb, false, 6),
  ('mission-be3-07', 'world-be-3', 'campaign-be3', 'operation-be3-2', 'blocking-the-event-loop', 'Blocking the Event Loop', 'The freeze incident, finally explained: any synchronous code that takes a long time to run blocks literally everything else, because there is only one thread running JavaScript.', 'intermediate', ARRAY['forge','mira'], '{"requiredMissionIds":["mission-be3-06"]}'::jsonb, null, '{"type":"simulation","simulationId":"blocking-handler-sim"}'::jsonb, '{"xp":120,"credits":20}'::jsonb, false, 7),
  ('mission-be3-08', 'world-be-3', 'campaign-be3', 'operation-be3-2', 'cpu-bound-work', 'CPU-bound Work', 'Waiting on a database is cheap for the thread. Computing something expensive is not -- and async/await doesn''t make computation itself go any faster.', 'intermediate', ARRAY['forge'], '{"requiredMissionIds":["mission-be3-07"]}'::jsonb, null, '{"type":"simulation","simulationId":"io-vs-cpu-sim"}'::jsonb, '{"xp":125,"credits":20}'::jsonb, false, 8),
  ('mission-be3-09', 'world-be-3', 'campaign-be3', 'operation-be3-2', 'worker-threads-concepts', 'Worker Threads Concepts', 'The actual fix for CPU-bound work: a separate thread to do the computing, talking back to the main thread only through messages.', 'intermediate', ARRAY['forge'], '{"requiredMissionIds":["mission-be3-08"]}'::jsonb, null, '{"type":"simulation","simulationId":"worker-threads-sim"}'::jsonb, '{"xp":130,"credits":22}'::jsonb, false, 9),
  ('mission-be3-10', 'world-be-3', 'campaign-be3', 'operation-be3-2', 'streams', 'Streams', 'The incident log itself is gigabytes now. Loading all of it into memory before touching a single byte is exactly the kind of mistake this Act has been building toward not making.', 'intermediate', ARRAY['forge'], '{"requiredMissionIds":["mission-be3-09"]}'::jsonb, null, '{"type":"simulation","simulationId":"streams-pipeline-sim"}'::jsonb, '{"xp":130,"credits":22}'::jsonb, false, 10),
  ('mission-be3-11', 'world-be-3', 'campaign-be3', 'operation-be3-2', 'buffers', 'Buffers', 'Every stream chunk is raw bytes before it''s ever a string. Compare one to text directly and the comparison quietly never matches.', 'intermediate', ARRAY['forge','mira'], '{"requiredMissionIds":["mission-be3-10"]}'::jsonb, null, '{"type":"simulation","simulationId":"buffers-encoding-sim"}'::jsonb, '{"xp":140,"credits":25}'::jsonb, false, 11),
  ('mission-be3-12', 'world-be-3', 'campaign-be3', 'operation-be3-2', 'event-loop-lockdown', 'Event Loop Lockdown', 'Mira asked for one resilience report. Generating it froze every other request on the service for a second and a half -- silently, with no crash and no error.', 'boss', ARRAY['mira','forge'], '{"requiredMissionIds":["mission-be3-11"]}'::jsonb, null, '{"type":"simulation","simulationId":"event-loop-lockdown-boss-sim"}'::jsonb, '{"xp":380,"credits":80,"badgeIds":["event-loop-lockdown"],"skillXp":{"backend_fundamentals":30}}'::jsonb, true, 12);

insert into public.dialogue_lines (mission_id, sort_order, character_id, text) values
  ('mission-be3-01', 1, 'mira', 'The server survived Port 8080. Stayed up a full week after that. Then it went quiet mid-shift -- not crashed, just... stopped answering, for exactly as long as one report took to generate.'),
  ('mission-be3-01', 2, 'forge', 'Before we chase that, you need the actual foundation under it. JavaScript runs one line at a time, in order, on one thread -- until it doesn''t. ''Blocking'' means nothing else can happen while a given line is still running.'),
  ('mission-be3-01', 3, 'forge', '''Asynchronous'' doesn''t mean ''runs somewhere else.'' It means ''starts something, then lets other work happen while that something finishes.'' Confuse those two and this whole Act stops making sense.'),
  ('mission-be3-02', 1, 'forge', 'Before promises existed, this was the entire pattern: hand a function a callback, and it calls that function back once the work is done. Simple with one step. Less simple stacked three or four deep.'),
  ('mission-be3-03', 1, 'forge', 'A Promise is an object that represents work that hasn''t finished yet. Exactly one of three states waits at the end of it: fulfilled, rejected, or -- if you never handle it -- forever pending.'),
  ('mission-be3-04', 1, 'forge', 'async/await is syntax sugar over exactly what you just learned. It doesn''t change what''s happening underneath -- it just lets asynchronous code read top to bottom instead of nested in .then() chains.'),
  ('mission-be3-04', 2, 'mira', 'Sugar is still real code. Forget the await and you''re holding a Promise object, not the value you asked for -- and that mistake reads as correct until it very much isn''t.'),
  ('mission-be3-05', 1, 'forge', 'Here''s the actual mechanism underneath every callback, promise and await you''ve used this Act: one call stack, one thread, and a loop that keeps checking whether there''s queued work to run once that stack empties out.'),
  ('mission-be3-05', 2, 'mira', 'This is the piece that actually explains the freeze. Learn it properly before we open the incident.'),
  ('mission-be3-06', 1, 'forge', 'Not every queue gets treated equally. Promise callbacks -- microtasks -- fully drain before the event loop even looks at the next timer. A setTimeout of 0ms was never a promise to run in zero milliseconds; it''s a promise to run after everything already ahead of it.'),
  ('mission-be3-07', 1, 'forge', 'Here''s the mechanism behind the freeze, finally: any synchronous code that takes a long time to run blocks literally everything else on the process, because there''s exactly one thread running your JavaScript.'),
  ('mission-be3-07', 2, 'mira', 'That includes routes that have nothing to do with whatever''s actually running. One slow handler doesn''t fail alone -- it takes the whole service down with it, silently, for as long as it runs.'),
  ('mission-be3-08', 1, 'forge', 'Waiting on a database or a network call is cheap for the thread -- it just isn''t doing anything during that wait. Actual computation is different. The thread is busy the entire time, and nothing about async/await changes how long computing something takes.'),
  ('mission-be3-09', 1, 'forge', 'The actual fix for CPU-bound work isn''t a cleverer async pattern. It''s a separate thread to do the computing on, talking back to the main thread only through messages -- never by sharing variables directly.'),
  ('mission-be3-10', 1, 'forge', 'The incident log itself is gigabytes now. Load all of it into memory before touching a single byte, and you''ve made the exact mistake this Act has been building toward not making. Streams let you start processing before the whole thing has even arrived.'),
  ('mission-be3-11', 1, 'forge', 'Every chunk a stream hands you is raw bytes first, not text -- a Buffer, not a string. Compare one directly to a string and the comparison quietly never matches, no error, no warning.'),
  ('mission-be3-11', 2, 'mira', 'Quiet mismatches are how we got here in the first place. Same lesson, new layer.'),
  ('mission-be3-12', 1, 'mira', 'I asked for one number: how resilient this service actually is, scored across every incident this month. Pull it into a report.'),
  ('mission-be3-12', 2, 'forge', 'Report went out. So did the service -- for one point four seconds, every other request just stopped answering. Not an error. Not a crash. Silence, then a flood of queued responses all at once.'),
  ('mission-be3-12', 3, 'mira', 'That shape is familiar. Find the mechanism, not just the symptom, before you touch a single line of code.'),
  ('mission-be3-12', 4, 'forge', 'Metrics, the actual handler, and one bad theory a teammate floated. Work through all three before you call it.'),
  ('mission-be3-12', 5, 'forge', '...one more thing. The last connection accepted before the freeze, timestamped to the millisecond it locked, came through a path with a doubled slash in it. Same signature as before. I''m starting a private log just for these.'),
  ('mission-be3-12', 6, 'mira', 'Keep it private for now. Three times isn''t a coincidence anymore, but it''s still not today''s fire. Fix the freeze.');

insert into public.objectives (id, mission_id, sort_order, title, description) values
  ('mission-be3-01-o1', 'mission-be3-01', 1, 'Define blocking', 'Say precisely what running synchronous code actually means for everything else on the thread.'),
  ('mission-be3-01-o2', 'mission-be3-01', 2, 'Read the freeze signature', 'Find the evidence that points at busy computation, not a crash or a stuck network call.'),
  ('mission-be3-02-o1', 'mission-be3-02', 1, 'Find the swapped arguments', 'Every caller expects Node''s standard callback convention. Find the line that breaks it.'),
  ('mission-be3-02-o2', 'mission-be3-02', 2, 'Name the pattern', 'Name what nesting dependent callbacks three levels deep is commonly called.'),
  ('mission-be3-03-o1', 'mission-be3-03', 1, 'Name the state', 'Identify a Promise''s state at the exact moment it''s created.'),
  ('mission-be3-03-o2', 'mission-be3-03', 2, 'Find the broken chain', 'The final result is always missing data. Find the line that breaks the chain.'),
  ('mission-be3-04-o1', 'mission-be3-04', 1, 'Find the missing await', 'This always returns undefined. Find the line missing the keyword that would fix it.'),
  ('mission-be3-04-o2', 'mission-be3-04', 2, 'Explain the unawaited call', 'Say what actually happens when an async function is called without being awaited.'),
  ('mission-be3-05-o1', 'mission-be3-05', 1, 'Order the mechanism', 'Order what actually happens between a script starting and a queued callback executing.'),
  ('mission-be3-05-o2', 'mission-be3-05', 2, 'Define single-threaded', 'Say what ''Node is single-threaded'' actually means in practice.'),
  ('mission-be3-06-o1', 'mission-be3-06', 1, 'Predict the print order', 'Work out the actual order four lines of mixed sync, microtask and timer code will print in.'),
  ('mission-be3-06-o2', 'mission-be3-06', 2, 'Explain the delay', 'Find the evidence that explains why a 0ms timeout didn''t fire immediately.'),
  ('mission-be3-07-o1', 'mission-be3-07', 1, 'Find the blocking call', 'Every other request stalls for the full duration of this one. Find the responsible line.'),
  ('mission-be3-07-o2', 'mission-be3-07', 2, 'Explain the blast radius', 'Explain why one slow handler freezes requests on completely unrelated routes.'),
  ('mission-be3-08-o1', 'mission-be3-08', 1, 'Sort the workloads', 'Sort each task into I/O-bound or CPU-bound.'),
  ('mission-be3-08-o2', 'mission-be3-08', 2, 'Judge the rewrite', 'Decide whether switching the handler to async/await alone actually fixes the freeze.'),
  ('mission-be3-09-o1', 'mission-be3-09', 1, 'Explain the fix', 'Say precisely what moving the computation into a worker thread actually changes.'),
  ('mission-be3-09-o2', 'mission-be3-09', 2, 'Read the message passing', 'Find the evidence that shows how the main thread and the worker actually exchange data.'),
  ('mission-be3-10-o1', 'mission-be3-10', 1, 'Judge the full read', 'Explain what''s actually wrong with reading a 4GB file into memory before processing it.'),
  ('mission-be3-10-o2', 'mission-be3-10', 2, 'Order the stream', 'Order what actually happens when a large file is read as a stream.'),
  ('mission-be3-11-o1', 'mission-be3-11', 1, 'Find the type mismatch', 'This comparison never matches, even on an exact text match. Find the line responsible.'),
  ('mission-be3-11-o2', 'mission-be3-11', 2, 'Name the default type', 'Identify what type a stream''s data event actually hands you by default.'),
  ('mission-be3-12-o1', 'mission-be3-12', 1, 'Read the freeze', 'Find the evidence that points directly at the actual mechanism of the freeze, not just its symptoms.'),
  ('mission-be3-12-o2', 'mission-be3-12', 2, 'Find the line', 'Find the exact line holding the event loop hostage for the full 1.4 seconds.'),
  ('mission-be3-12-o3', 'mission-be3-12', 3, 'Rule out the decoy', 'Judge a competing theory against the actual evidence.'),
  ('mission-be3-12-o4', 'mission-be3-12', 4, 'Fix the freeze', 'State the fix, tying the metrics, the code and the ruled-out theory together.');

insert into public.challenges (id, objective_id, sort_order, type, prompt, content, completion_conditions) values
  ('mission-be3-01-o1-c1', 'mission-be3-01-o1', 1, 'multiple_choice', 'Forge calls a loop that sums a million numbers "synchronous." What does that actually mean?', '{"question":"Forge calls a loop that sums a million numbers \"synchronous.\" What does that actually mean?","options":[{"id":"a","text":"It runs across multiple threads at once"},{"id":"b","text":"Every line runs to completion, in order, before the next line starts -- nothing else can happen on this thread until it finishes"},{"id":"c","text":"It never actually finishes"},{"id":"d","text":"It only works on arrays of numbers"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),
  ('mission-be3-01-o2-c1', 'mission-be3-01-o2', 1, 'investigation', 'Which evidence suggests the server wasn''t crashed or waiting on I/O, but was actually busy running synchronous code the whole time?', '{"evidence":[{"id":"ev1","label":"Incident log","detail":"No new requests were accepted for 850ms, then 40 queued requests were all answered within 5ms of each other"},{"id":"ev2","label":"CPU usage during the gap","detail":"Pinned at 100% on a single core for the entire 850ms"},{"id":"ev3","label":"Memory usage during the gap","detail":"Flat the entire time, no growth"}],"question":"Which evidence suggests the server wasn''t crashed or waiting on I/O, but was actually busy running synchronous code the whole time?"}'::jsonb, '{"requiredEvidenceIds":["ev1","ev2"]}'::jsonb),

  ('mission-be3-02-o1-c1', 'mission-be3-02-o1', 1, 'code_debugging', 'Every caller of loadDispatch expects Node''s standard convention: error first, then data. Which line breaks that convention?', '{"language":"javascript","code":"function loadDispatch(id, callback) {\n  db.query(id, (err, result) => {\n    callback(result, err);\n  });\n}\n\nloadDispatch(\"12\", (dispatch, err) => {\n  console.log(dispatch.unit);\n});","question":"Every caller of loadDispatch expects Node''s standard convention: error first, then data. Which line breaks that convention?"}'::jsonb, '{"requiredLineIds":["    callback(result, err);"]}'::jsonb),
  ('mission-be3-02-o2-c1', 'mission-be3-02-o2', 1, 'multiple_choice', 'Nesting a callback inside a callback inside a callback to sequence three dependent async steps is commonly called what?', '{"question":"Nesting a callback inside a callback inside a callback to sequence three dependent async steps is commonly called what?","options":[{"id":"a","text":"Promise chaining"},{"id":"b","text":"Callback hell, or the pyramid of doom -- each step nested one level deeper, indentation growing with every dependency"},{"id":"c","text":"Tail call optimization"},{"id":"d","text":"The event loop"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),

  ('mission-be3-03-o1-c1', 'mission-be3-03-o1', 1, 'multiple_choice', 'A Promise is created and immediately logged. What state is it in at that exact moment, before any async work resolves?', '{"question":"A Promise is created and immediately logged. What state is it in at that exact moment, before any async work resolves?","options":[{"id":"a","text":"fulfilled"},{"id":"b","text":"rejected"},{"id":"c","text":"pending"},{"id":"d","text":"settled"}]}'::jsonb, '{"correctOptionId":"c"}'::jsonb),
  ('mission-be3-03-o2-c1', 'mission-be3-03-o2', 1, 'code_debugging', 'The final result always has an undefined unit, even though fetchUnit succeeds every time. Which line is missing something that breaks the chain?', '{"language":"javascript","code":"function getDispatchWithUnit(id) {\n  return fetchDispatch(id).then((dispatch) => {\n    fetchUnit(dispatch.unitId);\n  }).then((unit) => {\n    return { unit };\n  });\n}","question":"The final result always has an undefined unit, even though fetchUnit succeeds every time. Which line is missing something that breaks the chain?"}'::jsonb, '{"requiredLineIds":["    fetchUnit(dispatch.unitId);"]}'::jsonb),

  ('mission-be3-04-o1-c1', 'mission-be3-04-o1', 1, 'code_debugging', 'This always throws or returns undefined, never the actual unit. Which line is missing the keyword that would fix it?', '{"language":"javascript","code":"async function getDispatch(id) {\n  const dispatch = fetchDispatch(id);\n  return dispatch.unit;\n}","question":"This always throws or returns undefined, never the actual unit. Which line is missing the keyword that would fix it?"}'::jsonb, '{"requiredLineIds":["  const dispatch = fetchDispatch(id);"]}'::jsonb),
  ('mission-be3-04-o2-c1', 'mission-be3-04-o2', 1, 'multiple_choice', 'An async function is called without being awaited, and the very next line executes immediately after. What actually happens?', '{"question":"An async function is called without being awaited, and the very next line executes immediately after. What actually happens?","options":[{"id":"a","text":"The program pauses until the async function finishes"},{"id":"b","text":"The async function starts running, but the next line executes immediately without waiting for it to finish -- the call returns a Promise that''s effectively ignored"},{"id":"c","text":"It throws a syntax error"},{"id":"d","text":"It automatically runs on a separate thread"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),

  ('mission-be3-05-o1-c1', 'mission-be3-05-o1', 1, 'interactive_diagram', 'Order what actually happens between a script starting and a queued callback executing.', '{"diagramId":"event-loop-mechanism","hotspots":[{"id":"sync_code","label":"Synchronous code runs on the call stack","explanation":"Every top-level line executes first, in order, before anything queued gets a turn."},{"id":"stack_empty","label":"The call stack becomes empty","explanation":"Nothing else can run until the currently executing code finishes and the stack clears."},{"id":"queue_check","label":"The event loop checks the callback queue","explanation":"Only once the stack is empty does the loop look for queued work to run."},{"id":"callback_runs","label":"A queued callback is pushed onto the stack and runs","explanation":"The callback executes as if it were ordinary synchronous code, one at a time."}],"task":"Order what actually happens between a script starting and a queued callback executing."}'::jsonb, '{"correctOrderIds":["sync_code","stack_empty","queue_check","callback_runs"]}'::jsonb),
  ('mission-be3-05-o2-c1', 'mission-be3-05-o2', 1, 'multiple_choice', 'Node is famously described as "single-threaded." What does that actually mean in practice?', '{"question":"Node is famously described as \"single-threaded.\" What does that actually mean in practice?","options":[{"id":"a","text":"It can only ever handle one request, ever"},{"id":"b","text":"Your JavaScript callback code all runs on one thread, one callback at a time -- but I/O itself (disk, network) happens off that thread, in the background"},{"id":"c","text":"It can only run on single-core machines"},{"id":"d","text":"Only one file can be open at a time"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),

  ('mission-be3-06-o1-c1', 'mission-be3-06-o1', 1, 'multiple_choice', 'console.log("A"); setTimeout(() => console.log("B"), 0); Promise.resolve().then(() => console.log("C")); console.log("D"); -- what''s the actual print order?', '{"question":"Given this sequence: console.log(\"A\"); setTimeout(() => console.log(\"B\"), 0); Promise.resolve().then(() => console.log(\"C\")); console.log(\"D\"); -- what''s the actual print order?","options":[{"id":"a","text":"A, B, C, D"},{"id":"b","text":"A, D, C, B"},{"id":"c","text":"A, D, B, C"},{"id":"d","text":"A, C, D, B"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),
  ('mission-be3-06-o2-c1', 'mission-be3-06-o2', 1, 'investigation', 'Which evidence explains why a 0ms timeout didn''t fire immediately?', '{"evidence":[{"id":"ev1","label":"Code","detail":"setTimeout(sendNotification, 0)"},{"id":"ev2","label":"Observed delay","detail":"sendNotification actually ran 12ms later, not 0ms later"},{"id":"ev3","label":"Trace in between","detail":"Two pending promise .then() callbacks and a chain of already-queued microtasks ran first"}],"question":"Which evidence explains why a 0ms timeout didn''t fire immediately?"}'::jsonb, '{"requiredEvidenceIds":["ev3"]}'::jsonb),

  ('mission-be3-07-o1-c1', 'mission-be3-07-o1', 1, 'code_debugging', 'Every other request stalls for the full duration of this one. Which line is actually responsible for blocking the whole process?', '{"language":"javascript","code":"app.get(\"/reports/resilience\", (req, res) => {\n  const summary = summarizeIncidents(incidentLog);\n  res.json(summary);\n});\n\nfunction summarizeIncidents(log) {\n  let total = 0;\n  for (let i = 0; i < log.length; i++) {\n    total += scoreIncident(log[i]);\n  }\n  return { total };\n}","question":"Every other request stalls for the full duration of this one. Which line is actually responsible for blocking the whole process?"}'::jsonb, '{"requiredLineIds":["  const summary = summarizeIncidents(incidentLog);"]}'::jsonb),
  ('mission-be3-07-o2-c1', 'mission-be3-07-o2', 1, 'multiple_choice', 'Why does one slow synchronous handler freeze every other request, even ones for a completely unrelated route?', '{"question":"Why does one slow synchronous handler freeze every other request, even ones for a completely unrelated route?","options":[{"id":"a","text":"It doesn''t -- other routes run on separate threads automatically"},{"id":"b","text":"Node runs all your JavaScript callbacks on a single thread; while that thread is busy with synchronous code, it can''t start processing any other callback, including other requests'' handlers"},{"id":"c","text":"Only that specific route actually freezes"},{"id":"d","text":"It only affects requests coming from the same client"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),

  ('mission-be3-08-o1-c1', 'mission-be3-08-o1', 1, 'drag_and_drop', 'Sort each task into I/O-bound or CPU-bound.', '{"items":[{"id":"i1","text":"Querying the database for a dispatch record"},{"id":"i2","text":"Compressing a 50MB log file synchronously"},{"id":"i3","text":"Reading a file from disk"},{"id":"i4","text":"Computing SHA-256 hashes over a million records"},{"id":"i5","text":"Waiting on a response from the notification service"}],"targets":[{"id":"io","label":"I/O-bound (mostly waiting)"},{"id":"cpu","label":"CPU-bound (mostly computing)"}]}'::jsonb, '{"correctMapping":{"i1":"io","i2":"cpu","i3":"io","i4":"cpu","i5":"io"}}'::jsonb),
  ('mission-be3-08-o2-c1', 'mission-be3-08-o2', 1, 'multiple_choice', 'Someone rewrites the resilience report handler to use async/await, hoping it fixes the freeze. Does it?', '{"question":"Someone rewrites the resilience report handler to use async/await, hoping it fixes the freeze. Does it?","options":[{"id":"a","text":"Yes, async/await makes any function non-blocking"},{"id":"b","text":"No -- await only yields control while genuinely waiting on something external (I/O); a synchronous CPU-heavy loop still runs to completion on the main thread and blocks it either way"},{"id":"c","text":"Yes, because async functions run on a separate thread automatically"},{"id":"d","text":"No, because async/await doesn''t exist in Node.js"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),

  ('mission-be3-09-o1-c1', 'mission-be3-09-o1', 1, 'multiple_choice', 'What does moving the report calculation into a worker thread actually change?', '{"question":"What does moving the report calculation into a worker thread actually change?","options":[{"id":"a","text":"Nothing, it still runs on the main thread"},{"id":"b","text":"It moves the CPU-heavy computation onto a separate thread, so the main thread''s event loop stays free to keep handling requests while the worker computes"},{"id":"c","text":"It makes the computation finish instantly"},{"id":"d","text":"It converts the code to run in parallel across the network"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),
  ('mission-be3-09-o2-c1', 'mission-be3-09-o2', 1, 'investigation', 'Which pieces of evidence show how the main thread and the worker thread actually exchange the report data?', '{"evidence":[{"id":"ev1","label":"Worker code","detail":"worker.postMessage({ log: incidentLog })"},{"id":"ev2","label":"Main thread code","detail":"worker.on(\"message\", (summary) => { res.json(summary); })"},{"id":"ev3","label":"Direct access attempt","detail":"Reading a variable defined inside the worker file directly from the main thread returns undefined -- it isn''t shared"}],"question":"Which pieces of evidence show how the main thread and the worker thread actually exchange the report data?"}'::jsonb, '{"requiredEvidenceIds":["ev1","ev2"]}'::jsonb),

  ('mission-be3-10-o1-c1', 'mission-be3-10-o1', 1, 'multiple_choice', 'The full incident log is 4GB. What''s the actual problem with reading it all into memory before processing?', '{"question":"The full incident log is 4GB. What''s the actual problem with reading it all into memory before processing it?","options":[{"id":"a","text":"Nothing, memory is effectively unlimited"},{"id":"b","text":"It blocks the event loop for the entire read and requires enough memory to hold all 4GB at once, when most of the processing could happen incrementally as data arrives"},{"id":"c","text":"Synchronous file reads don''t exist in Node"},{"id":"d","text":"It''s exactly as fast as streaming, just written with less code"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),
  ('mission-be3-10-o2-c1', 'mission-be3-10-o2', 1, 'interactive_diagram', 'Order what actually happens when a large file is read as a stream.', '{"diagramId":"stream-read-pipeline","hotspots":[{"id":"open","label":"The stream opens and starts reading from disk","explanation":"Reading begins immediately, without waiting for the whole file to be available."},{"id":"data","label":"A \"data\" event fires once a chunk becomes available","explanation":"This repeats for every chunk, as each one arrives, rather than all at once."},{"id":"process_chunk","label":"Each chunk is processed as it arrives","explanation":"Work can start on the first chunk before the last chunk has even been read."},{"id":"end","label":"An \"end\" event fires once no chunks remain","explanation":"This is the only reliable signal that the whole file has actually been read."}],"task":"Order what actually happens when a large file is read as a stream."}'::jsonb, '{"correctOrderIds":["open","data","process_chunk","end"]}'::jsonb),

  ('mission-be3-11-o1-c1', 'mission-be3-11-o1', 1, 'code_debugging', 'This comparison never matches, even when the client sends exactly the text "ping". Which line is the bug?', '{"language":"javascript","code":"req.on(\"data\", (chunk) => {\n  if (chunk === \"ping\") {\n    res.end(\"pong\");\n  }\n  body += chunk;\n});","question":"This comparison never matches, even when the client sends exactly the text \"ping\". Which line is the bug?"}'::jsonb, '{"requiredLineIds":["  if (chunk === \"ping\") {"]}'::jsonb),
  ('mission-be3-11-o2-c1', 'mission-be3-11-o2', 1, 'multiple_choice', 'By default, what type is the chunk argument passed to a stream''s data event?', '{"question":"By default, what type is the chunk argument passed to a stream''s data event?","options":[{"id":"a","text":"A plain JavaScript string"},{"id":"b","text":"A Buffer -- a raw sequence of bytes, which needs .toString() (or an explicit encoding) to become a string"},{"id":"c","text":"An array of numbers"},{"id":"d","text":"Always pre-parsed JSON"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),

  ('mission-be3-12-o1-c1', 'mission-be3-12-o1', 1, 'investigation', 'Which pieces of evidence point directly at the actual mechanism of the freeze, not just its symptoms?', '{"evidence":[{"id":"ev1","label":"Metrics","detail":"0 requests completed for 1.4 seconds, then 63 queued requests all completed within 8ms of each other"},{"id":"ev2","label":"CPU","detail":"Pinned at 100% on the main thread for the entire 1.4 second gap"},{"id":"ev3","label":"Route hit immediately before the gap","detail":"POST /reports/resilience"},{"id":"ev4","label":"Handler code for that route","detail":"Runs a synchronous scoring pass over every incident from the last 30 days, in a single function call, on the request thread"}],"question":"Which pieces of evidence point directly at the actual mechanism of the freeze, not just its symptoms?"}'::jsonb, '{"requiredEvidenceIds":["ev2","ev4"]}'::jsonb),
  ('mission-be3-12-o2-c1', 'mission-be3-12-o2', 1, 'code_debugging', 'Which line is the one actually holding the event loop hostage for the full 1.4 seconds?', '{"language":"javascript","code":"app.post(\"/reports/resilience\", (req, res) => {\n  const report = buildResilienceReport(incidentLog);\n  res.json(report);\n});\n\nfunction buildResilienceReport(log) {\n  let score = 0;\n  for (const incident of log) {\n    score += computeSeverityScore(incident);\n  }\n  return { score, count: log.length };\n}","question":"Which line is the one actually holding the event loop hostage for the full 1.4 seconds?"}'::jsonb, '{"requiredLineIds":["  const report = buildResilienceReport(incidentLog);"]}'::jsonb),
  ('mission-be3-12-o3-c1', 'mission-be3-12-o3', 1, 'multiple_choice', 'A teammate suggests the freeze was a database timeout, since the report reads from the incident log. Does the evidence support that?', '{"question":"A teammate suggests the freeze was a database timeout, since the report reads from the incident log. Does the evidence support that?","options":[{"id":"a","text":"Yes, database calls are always the cause of freezes"},{"id":"b","text":"No -- a database call is I/O and would show the thread idle, waiting; this freeze shows the CPU pinned at 100% the entire time, which points at computation, not waiting"},{"id":"c","text":"Unknowable without restarting the database"},{"id":"d","text":"Yes, because the report request eventually failed"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),
  ('mission-be3-12-o4-c1', 'mission-be3-12-o4', 1, 'boss_encounter', 'Having traced the metrics, the exact line, and ruled out the database theory, state the fix.', '{"stages":[{"objectiveRef":"mission-be3-12-o1","label":"Read the freeze"},{"objectiveRef":"mission-be3-12-o2","label":"Find the line"},{"objectiveRef":"mission-be3-12-o3","label":"Rule out the decoy"}],"task":"Having traced the metrics, the exact line, and ruled out the database theory, state the fix: the resilience report''s scoring pass is synchronous, CPU-bound work running directly on the request thread -- move it off that thread entirely (a worker thread), or break it into small asynchronous chunks that yield back to the event loop, so no single computation can hold every other request hostage again."}'::jsonb, '{"requiredObjectiveIds":["mission-be3-12-o1","mission-be3-12-o2","mission-be3-12-o3"],"allCorrect":true}'::jsonb);

insert into public.hints (challenge_id, tier, text, xp_cost, sort_order) values
  ('mission-be3-01-o1-c1', 'orientation', 'Think about what has to be true for the next line to even start.', 10, 1),
  ('mission-be3-01-o1-c1', 'solution', 'Synchronous means every line runs to completion, in order, before the next one starts -- the thread has nothing else to give until this line is done.', 20, 2),
  ('mission-be3-01-o2-c1', 'orientation', 'A crash would leave a gap in the log with no clean recovery. A stuck network call would leave the thread idle, not busy.', 10, 1),
  ('mission-be3-01-o2-c1', 'concept', 'A single core pinned at 100% for the exact duration of a gap is the signature of computation, not waiting.', 20, 2),
  ('mission-be3-01-o2-c1', 'solution', 'ev1 shows requests queuing then releasing all at once -- the classic shape of a blocked thread catching up -- and ev2 shows the CPU was actually busy computing that whole time, not idle waiting on I/O.', 30, 3),

  ('mission-be3-02-o1-c1', 'orientation', 'Node''s convention has a name: error-first callbacks. Check the argument order against it.', 10, 1),
  ('mission-be3-02-o1-c1', 'concept', 'db.query already follows (err, result) -- error first. loadDispatch has to preserve that order when it forwards the call.', 20, 2),
  ('mission-be3-02-o1-c1', 'solution', 'callback(result, err); passes the arguments in the wrong order -- it should be callback(err, result); to match the convention every caller expects.', 30, 3),
  ('mission-be3-02-o2-c1', 'orientation', 'Picture what the code looks like on the page as each dependent step gets nested one level deeper.', 10, 1),
  ('mission-be3-02-o2-c1', 'solution', 'Callback hell, or the pyramid of doom -- indentation grows with every dependent async step nested inside the last one''s callback.', 20, 2),

  ('mission-be3-03-o1-c1', 'orientation', 'The work the Promise wraps hasn''t had a chance to finish yet at the instant it''s created.', 10, 1),
  ('mission-be3-03-o1-c1', 'solution', 'A newly created Promise is pending -- it moves to fulfilled or rejected only once the work it wraps actually settles.', 20, 2),
  ('mission-be3-03-o2-c1', 'orientation', '.then() only passes a value forward to the next .then() if something is actually returned from it.', 10, 1),
  ('mission-be3-03-o2-c1', 'concept', 'Calling a function that returns a Promise, without returning that Promise yourself, breaks the chain -- the outer chain moves on without waiting for it.', 20, 2),
  ('mission-be3-03-o2-c1', 'solution', 'fetchUnit(dispatch.unitId); is called but never returned, so the next .then() doesn''t actually wait for it and receives undefined instead of the resolved unit.', 30, 3),

  ('mission-be3-04-o1-c1', 'orientation', 'fetchDispatch is presumably asynchronous -- what does calling an async function actually hand you immediately?', 10, 1),
  ('mission-be3-04-o1-c1', 'concept', 'Without await, you get the Promise object itself, not the value it will eventually resolve to. A Promise has no .unit property.', 20, 2),
  ('mission-be3-04-o1-c1', 'solution', 'const dispatch = fetchDispatch(id); is missing await -- it should be const dispatch = await fetchDispatch(id); so dispatch is the resolved value, not a Promise.', 30, 3),
  ('mission-be3-04-o2-c1', 'orientation', 'async doesn''t mean ''blocks the caller.'' It means ''returns a Promise, eventually.''', 10, 1),
  ('mission-be3-04-o2-c1', 'solution', 'The async function starts running, but control returns to the next line immediately -- its returned Promise is simply never looked at, so nothing waits for it and any rejection goes unhandled.', 20, 2),

  ('mission-be3-05-o1-c1', 'orientation', 'Nothing queued gets a turn while the call stack still has work on it.', 10, 1),
  ('mission-be3-05-o1-c1', 'solution', 'Synchronous code runs first, the stack empties, the loop checks the queue, then a queued callback finally gets pushed on and runs.', 20, 2),
  ('mission-be3-05-o2-c1', 'orientation', 'Single-threaded describes where your callback code runs -- not where every part of Node''s work happens.', 10, 1),
  ('mission-be3-05-o2-c1', 'solution', 'Your JavaScript runs one callback at a time on one thread; the actual I/O work (disk, network) happens off that thread in the background, and only the completion callback comes back to the single thread.', 20, 2),

  ('mission-be3-06-o1-c1', 'orientation', 'Split this into three groups: what runs immediately, what''s a microtask, and what''s a timer.', 10, 1),
  ('mission-be3-06-o1-c1', 'concept', 'All synchronous code finishes first. Then every pending microtask (promise callbacks) runs before the event loop even looks at the timer queue.', 20, 2),
  ('mission-be3-06-o1-c1', 'solution', 'A and D are synchronous and print immediately; C is a microtask and drains next; B is a timer callback and always runs last, even at 0ms.', 30, 3),
  ('mission-be3-06-o2-c1', 'orientation', 'A 0ms timeout isn''t a promise to run at time zero -- it''s a promise to run after everything ahead of it in the queues.', 10, 1),
  ('mission-be3-06-o2-c1', 'solution', 'ev3: the microtask queue -- pending promise callbacks -- fully drains before the event loop moves on to check the timer queue at all, which is what pushed the 0ms callback out to 12ms.', 20, 2),

  ('mission-be3-07-o1-c1', 'orientation', 'The route handler calls exactly one function that does real work -- find it.', 10, 1),
  ('mission-be3-07-o1-c1', 'concept', 'summarizeIncidents runs a plain synchronous loop directly on the request thread, with no await, no yielding, nothing letting other work interleave.', 20, 2),
  ('mission-be3-07-o1-c1', 'solution', 'const summary = summarizeIncidents(incidentLog); is what actually blocks -- the entire loop inside it runs to completion on the main thread before res.json can even be reached.', 30, 3),
  ('mission-be3-07-o2-c1', 'orientation', '''Unrelated route'' is a distinction that exists in your route table, not on the thread actually executing your code.', 10, 1),
  ('mission-be3-07-o2-c1', 'solution', 'All callback code -- regardless of which route it belongs to -- runs on the same single thread; while that thread is occupied by one handler''s synchronous work, no other handler''s callback can start, related route or not.', 20, 2),

  ('mission-be3-08-o1-c1', 'orientation', 'Ask of each task: is the thread mostly waiting, or mostly computing?', 10, 1),
  ('mission-be3-08-o1-c1', 'solution', 'i1, i3 and i5 are I/O-bound (the thread is idle, waiting on something external); i2 and i4 are CPU-bound (the thread is actively computing the entire time).', 20, 2),
  ('mission-be3-08-o2-c1', 'orientation', 'await only actually yields control while something external is being waited on.', 10, 1),
  ('mission-be3-08-o2-c1', 'concept', 'A synchronous for-loop has nothing to await -- there''s no external operation to wait on, only computation to run.', 20, 2),
  ('mission-be3-08-o2-c1', 'solution', 'No: wrapping a CPU-heavy synchronous loop in an async function changes nothing about how long it runs or that it still runs to completion on the main thread, blocking it exactly as before.', 30, 3),

  ('mission-be3-09-o1-c1', 'orientation', 'The computation itself doesn''t get faster -- what changes is which thread is stuck doing it.', 10, 1),
  ('mission-be3-09-o1-c1', 'solution', 'It moves the CPU-heavy work off the main thread entirely, so the main thread''s event loop is free to keep accepting and handling other requests while the worker computes in parallel.', 20, 2),
  ('mission-be3-09-o2-c1', 'orientation', 'Workers don''t share variables with the main thread by default -- something has to actively carry the data across.', 10, 1),
  ('mission-be3-09-o2-c1', 'solution', 'ev1 and ev2: the worker sends its result with postMessage, and the main thread receives it through a message event handler -- that''s the entire channel, not shared memory.', 20, 2),

  ('mission-be3-10-o1-c1', 'orientation', 'Two separate costs are hiding in ''read it all first'': how long it takes, and how much has to fit in memory at once.', 10, 1),
  ('mission-be3-10-o1-c1', 'solution', 'A full synchronous read blocks the event loop for the entire operation and needs 4GB of memory available all at once, when a stream could start processing the first chunk long before the last one even arrives.', 20, 2),
  ('mission-be3-10-o2-c1', 'orientation', 'Nothing waits for the whole file before doing anything -- that''s the entire point of a stream.', 10, 1),
  ('mission-be3-10-o2-c1', 'solution', 'The stream opens and starts reading, a data event fires per chunk as it arrives, each chunk gets processed as it comes in, and an end event fires only once nothing remains.', 20, 2),

  ('mission-be3-11-o1-c1', 'orientation', 'What type does a data event''s chunk actually arrive as, by default?', 10, 1),
  ('mission-be3-11-o1-c1', 'concept', 'A Buffer and a string are different types in JavaScript -- strict equality never treats them as equal, no matter what bytes the Buffer holds.', 20, 2),
  ('mission-be3-11-o1-c1', 'solution', 'if (chunk === "ping") compares a Buffer object to a string with strict equality, which is always false -- convert first with chunk.toString() === "ping".', 30, 3),
  ('mission-be3-11-o2-c1', 'orientation', 'Recall what just broke the comparison in the previous objective.', 10, 1),
  ('mission-be3-11-o2-c1', 'solution', 'By default a stream hands you a Buffer -- raw bytes -- and it takes an explicit .toString() or an encoding option to turn that into a JavaScript string.', 20, 2),

  ('mission-be3-12-o1-c1', 'orientation', 'One piece of evidence names the symptom. Two others point at the actual mechanism behind it.', 10, 1),
  ('mission-be3-12-o1-c1', 'solution', 'ev2 (CPU pinned at 100% the entire gap) and ev4 (a synchronous scoring pass run in a single call on the request thread) together explain the mechanism -- ev1 and ev3 describe the symptom and the trigger, not the cause.', 20, 2),
  ('mission-be3-12-o2-c1', 'orientation', 'The route handler calls exactly one function that does the real, expensive work.', 10, 1),
  ('mission-be3-12-o2-c1', 'concept', 'buildResilienceReport runs entirely synchronously -- no await, nothing yielding control back to the event loop until its loop finishes completely.', 20, 2),
  ('mission-be3-12-o2-c1', 'solution', 'const report = buildResilienceReport(incidentLog); is the line that blocks -- everything inside that function call has to finish before the thread is free for anything else.', 30, 3),
  ('mission-be3-12-o3-c1', 'orientation', 'A database timeout would leave the thread idle, waiting. Compare that against what the CPU metric actually showed.', 10, 1),
  ('mission-be3-12-o3-c1', 'solution', 'A real database timeout is I/O -- the thread would sit idle while waiting. This incident shows the CPU pinned at 100% for the entire gap, which is the signature of active computation, not a stalled network call.', 20, 2),
  ('mission-be3-12-o4-c1', 'orientation', 'All three findings point at the same kind of fix: get the computation off the thread that also has to answer everyone else.', 15, 1),
  ('mission-be3-12-o4-c1', 'solution', 'Move the scoring pass off the main thread into a worker thread, or break it into small chunks that yield back to the event loop between pieces -- either way, no single computation should ever again be able to hold every other request hostage.', 25, 2);
